import type { Attribution } from '@facefit/contracts';
import { integer, jsonb, pgTable, text } from 'drizzle-orm/pg-core';

export interface DimensionsMm {
  total: number;
  lensWidth: number;
  lensHeight: number;
  bridge: number;
  templeLength: number;
}

export type Vec3 = [number, number, number];

export interface Anchors {
  bridgeCenter: Vec3;
  nosePadLeft: Vec3;
  nosePadRight: Vec3;
  hingeLeft: Vec3;
  hingeRight: Vec3;
}

// The id comes from assets/catalog.json, so it is not generated by the database.
export const products = pgTable('products', {
  id: integer('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description').notNull(),
  category: text('category').notNull(),
  type: text('type').notNull(),
  modelPath: text('model_path').notNull(),
  dimensionsMm: jsonb('dimensions_mm').$type<DimensionsMm>().notNull(),
  dimensionsSource: text('dimensions_source').notNull(),
  bridgeOriginMm: jsonb('bridge_origin_mm').$type<Vec3>().notNull(),
  anchors: jsonb('anchors').$type<Anchors>().notNull(),
  attribution: jsonb('attribution').$type<Attribution>().notNull(),
});

export type ProductRow = typeof products.$inferSelect;
